#include "../../research/cubiomes/finders.h"
#include <stdio.h>
#include <math.h>
static double dist(Pos a,Pos b){return hypot(a.x-b.x,a.z-b.z);}
int main(){Generator g;setupGenerator(&g,MC_1_16_5,0);int found=0;for(uint64_t s=1;s<5000000&&found<12;s++){Pos v,r,f,b;int yes=0;for(int x=-1;x<=0;x++)for(int z=-1;z<=0;z++){if(!getStructurePos(Village,MC_1_16_5,s,x,z,&v)||hypot(v.x,v.z)>160)continue;for(int rx=-1;rx<=0;rx++)for(int rz=-1;rz<=0;rz++){if(!getStructurePos(Ruined_Portal,MC_1_16_5,s,rx,rz,&r)||dist(v,r)>100)continue;Pos n={r.x/8,r.z/8};for(int fx=-1;fx<=0;fx++)for(int fz=-1;fz<=0;fz++){if(!getStructurePos(Fortress,MC_1_16_5,s,fx,fz,&f)||dist(f,n)>180)continue;for(int bx=-1;bx<=0;bx++)for(int bz=-1;bz<=0;bz++){if(!getStructurePos(Bastion,MC_1_16_5,s,bx,bz,&b)||dist(b,n)>180||dist(b,f)>220)continue;applySeed(&g,DIM_OVERWORLD,s);if(!isViableStructurePos(Village,&g,v.x,v.z,0)||!isViableStructurePos(Ruined_Portal,&g,r.x,r.z,0))continue;Pos spawn=getSpawn(&g);if(dist(spawn,v)>150)continue;applySeed(&g,DIM_NETHER,s);if(!isViableStructurePos(Bastion,&g,b.x,b.z,0))continue;printf("{\"seed\":\"%llu\",\"spawn\":[%d,%d],\"village\":[%d,%d],\"ruin\":[%d,%d],\"fortress\":[%d,%d],\"bastion\":[%d,%d]}\n",(unsigned long long)s,spawn.x,spawn.z,v.x,v.z,r.x,r.z,f.x,f.z,b.x,b.z);fflush(stdout);found++;yes=1;goto next;}}}}next:;}}
